public static class AutoQaDeathReloadRegression{
 const string K="AUTO_QA.Death013";const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static object Get(object o,string f)=>o.GetType().GetField(f,F).GetValue(o);static object Write(string take,object data){File.WriteAllText("AUTO_QA/Evidence/"+take+".json",Newtonsoft.Json.JsonConvert.SerializeObject(data,Newtonsoft.Json.Formatting.Indented));return data;}
 static void Guard(){if(!Application.isPlaying||SceneManager.sceneCount!=1||!string.IsNullOrEmpty(SceneManager.GetActiveScene().path))throw new Exception("Requires isolated Play scene");}
 static void Check(List<object> rows,bool ok,string label)=>rows.Add(new{ok,label});static async Task Frames(int n){var limit=DateTime.UtcNow.AddSeconds(8);int end=Time.frameCount+n;while(Time.frameCount<end){if(!Application.isPlaying||DateTime.UtcNow>limit)throw new Exception("Frame timeout");await Task.Delay(5);}}
 public static async Task<object> Prepare(string take){Guard();if(!string.IsNullOrEmpty(SessionState.GetString(K+".Take","")))throw new Exception("Prior fixture exists");if(HealingPackSupply.Remaining!=HealingPackSupply.Total)throw new Exception("Preserve non-full healing ledger");SessionState.SetString(K+".Take",take);SessionState.SetFloat(K+".Time",Time.timeScale);SessionState.SetInt(K+".Cursor",(int)Cursor.lockState);SessionState.SetBool(K+".Visible",Cursor.visible);var root=new GameObject("AUTO_QA Death Reload");root.SetActive(false);var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.SetParent(root.transform,false);floor.transform.position=new Vector3(0,-.5f,0);floor.transform.localScale=new Vector3(30,1,30);var cameraObject=new GameObject("AUTO_QA Death camera",typeof(Camera));cameraObject.transform.SetParent(root.transform,false);cameraObject.tag="MainCamera";cameraObject.transform.position=new Vector3(0,3,-6);var actor=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/Prefabs/Characters/Sahur/SahurPlayer.prefab"),root.transform);actor.AddComponent<GameSaveExcluded>();actor.transform.position=Vector3.up;root.SetActive(true);SessionState.SetInt(K+".Root",root.GetInstanceID());SessionState.SetInt(K+".Actor",actor.GetInstanceID());await Frames(10);var death=actor.GetComponent<PlayerDeathRespawn>();var hp=actor.GetComponent<PlayerHealth>();var flash=actor.GetComponent<CombatDamageFlash>();flash.enabled=false;SessionState.SetInt(K+".Flash",flash.GetInstanceID());hp.currentHealth=0;death.Die();await Frames(2);var rows=new List<object>();var disabled=(List<Behaviour>)Get(death,"disabled");SessionState.SetString(K+".Disabled",string.Join(",",disabled.Select(b=>b.GetInstanceID())));SessionState.SetInt(K+".Overlay",((GameObject)Get(death,"overlay")).GetInstanceID());Check(rows,death.IsDead&&PlayerDeathRespawn.IsOpen&&Time.timeScale==0,"Fresh death owns global death pause");Check(rows,disabled.Count>=2&&disabled.All(b=>!b.enabled),"Death disables owned combat/movement behaviours");
 var labels=new GameObject("AUTO_QA localization labels",typeof(RectTransform),typeof(Canvas));labels.transform.SetParent(root.transform,false);var legacyGo=new GameObject("Legacy",typeof(RectTransform),typeof(Text));legacyGo.transform.SetParent(labels.transform,false);var legacy=legacyGo.GetComponent<Text>();legacy.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");legacy.text="主菜单";LocalizedGameText.Bind(legacy);var tmpGo=new GameObject("TMP",typeof(RectTransform),typeof(TextMeshProUGUI));tmpGo.transform.SetParent(labels.transform,false);var tmp=tmpGo.GetComponent<TextMeshProUGUI>();tmp.text="主菜单";LocalizedGameText.Bind(tmp);SessionState.SetInt(K+".Legacy",legacy.GetInstanceID());SessionState.SetInt(K+".Tmp",tmp.GetInstanceID());await Frames(2);Check(rows,legacy.text=="MAIN MENU"&&tmp.text=="MAIN MENU","Fresh legacy and TMP labels translate known alias");SessionState.SetString(K+".Assembly",typeof(AutoQaDeathReloadRegression).Assembly.GetName().Name);return Write(take+"-before",new{rows,disabled=disabled.Select(b=>b.GetType().Name).ToArray(),frame=Time.frameCount});}
 public static async Task<object> AfterReload(){Guard();var actor=EditorUtility.EntityIdToObject(SessionState.GetInt(K+".Actor",0)) as GameObject;var death=actor.GetComponent<PlayerDeathRespawn>();var rows=new List<object>();Check(rows,!AppDomain.CurrentDomain.GetAssemblies().Any(a=>a.GetName().Name==SessionState.GetString(K+".Assembly","")),"Actual reload unloaded preparation assembly");Check(rows,death.IsDead&&PlayerDeathRespawn.IsOpen&&Time.timeScale==0,"Reload preserves global death ownership");Check(rows,death.PanelVisible,"Death panel stays reachable after reload");var ids=SessionState.GetString(K+".Disabled","").Split(',').Select(int.Parse).ToArray();var disabled=(List<Behaviour>)Get(death,"disabled");Check(rows,disabled.Count==ids.Length&&disabled.Select(b=>b.GetInstanceID()).SequenceEqual(ids),"Reload preserves exact disabled behaviour ownership");var legacy=EditorUtility.EntityIdToObject(SessionState.GetInt(K+".Legacy",0)) as Text;var tmp=EditorUtility.EntityIdToObject(SessionState.GetInt(K+".Tmp",0)) as TMP_Text;legacy.text="主菜单";tmp.text="主菜单";await Frames(3);Check(rows,legacy.text=="MAIN MENU"&&tmp.text=="MAIN MENU","Native label updates continue after reload");legacy.enabled=false;legacy.enabled=true;legacy.text="Unmapped dynamic number 42";tmp.text="Unmapped dynamic number 17";await Frames(3);Check(rows,legacy.text=="Unmapped dynamic number 42"&&tmp.text=="Unmapped dynamic number 17","Unknown dynamic labels preserved");
 var respawnButton=((GameObject)EditorUtility.EntityIdToObject(SessionState.GetInt(K+".Overlay",0))).GetComponentInChildren<Button>(true);respawnButton.onClick.Invoke();Check(rows,!death.IsDead&&Time.timeScale>0,"Authored Respawn button remains wired after reload");string respawnError=null;bool respawned=!death.IsDead;try{if(!respawned)respawned=death.Respawn();}catch(Exception e){respawnError=e.GetType().Name+": "+e.Message;}Check(rows,respawnError==null&&respawned&&!death.IsDead&&Time.timeScale>0,"Respawn after actual reload completes");Check(rows,ids.All(id=>(EditorUtility.EntityIdToObject(id) as Behaviour)?.enabled==true),"Respawn restores all death-owned behaviours");Check(rows,!(EditorUtility.EntityIdToObject(SessionState.GetInt(K+".Flash",0)) as Behaviour).enabled,"Respawn preserves originally disabled component");Check(rows,!((GameObject)EditorUtility.EntityIdToObject(SessionState.GetInt(K+".Overlay",0))).activeSelf,"Respawn hides original death canvas");death.enabled=false;death.enabled=true;var hpAgain=actor.GetComponent<PlayerHealth>();hpAgain.currentHealth=0;hpAgain.OnDeath.Invoke();Check(rows,death.IsDead&&PlayerDeathRespawn.IsOpen,"Reenable restores immediate health death-event binding");respawnButton.onClick.Invoke();Check(rows,!death.IsDead&&ids.All(id=>(EditorUtility.EntityIdToObject(id) as Behaviour)?.enabled==true),"Reenabled death screen button supports another full respawn");return Write(SessionState.GetString(K+".Take","")+"-after",new{rows,respawnError,disabledCount=disabled.Count,frame=Time.frameCount});}
 public static object Cleanup(){var take=SessionState.GetString(K+".Take","");foreach(var key in new[]{"Root","Overlay"}){var go=EditorUtility.EntityIdToObject(SessionState.GetInt(K+"."+key,0)) as GameObject;if(go)UnityEngine.Object.DestroyImmediate(go);}Time.timeScale=SessionState.GetFloat(K+".Time",1);Cursor.lockState=(CursorLockMode)SessionState.GetInt(K+".Cursor",0);Cursor.visible=SessionState.GetBool(K+".Visible",true);foreach(var key in new[]{"Root","Actor","Overlay","Flash","Legacy","Tmp","Cursor"})SessionState.EraseInt(K+"."+key);foreach(var key in new[]{"Take","Disabled","Assembly"})SessionState.EraseString(K+"."+key);SessionState.EraseFloat(K+".Time");SessionState.EraseBool(K+".Visible");return Write(take+"-cleanup",new{cleaned=true,paused=PlayerDeathRespawn.IsOpen,timeScale=Time.timeScale});}
